      "confidence": 0.95
    },
    {
      "category": "bridged_nets",
      "components": ["R2", "Q1", "Q2"],
      "pins": ["R2.1", "R2.2", "Q1.1", "Q2.3"],
      "nets": ["PWM", "Q1 gate"],
      "observed": "R2 (1K) is connected between the PWM net and the gate of Q1 (the node also connected to Q2 collector and R1).",
      "expected": "Q1 gate should only be driven by Q2 collector and R1 pull-up; R2 should not connect PWM directly to Q1 gate.",
      "evidence": [
        {"source": "schematic", "quote": "Sheet 1: R2 1K with one side to PWM label, other side to Q1 gate node."}
      ],
      "impact": "The PWM signal directly drives the P-MOSFET gate, bypassing the inverter. Q1 may be always on, defeating the fan power switching function.",
      "confidence": 0.9
    },
    {
      "category": "other",
      "components": ["R6"],
      "pins": ["R6.1", "R6.2"],
      "nets": ["VCC", "TACH"],
      "observed": "R6 (10K) is connected between VCC and TACH.",
      "expected": "The TACH pull-up should be to +5V (the MCU supply), not to VCC (the unregulated input, which is >5V due to the LM1117-5.0 regulator).",
      "evidence": [
        {"source": "schematic", "quote": "Sheet 1: R6 10K top to VCC, bottom to TACH."}
      ],
      "impact": "If VCC is greater than 5V, the TACH input to the MCU may exceed its absolute maximum rating, potentially damaging the MCU.",
      "confidence": 0.85
    }
  ],
  "summary": "The schematic contains three significant anomalies: the I2C clock line (SCL) is not connected to the MCU (labeled SCK instead), R2 directly bridges the PWM signal to the fan power MOSFET gate, and R6 pulls up the TACH input to the unregulated VCC rail instead of +5V."
}

